-- Ported Supabase RLS — generated by scripts/extract-rls-policies.mjs
--
-- Every auth.uid()/auth.email()/auth.jwt() reference was translated to the
-- actor-GUC helpers from migration 004. Policies keep their original
-- TO-clause role names (authenticated / service_role / public); the API
-- proxy runs queries as app_user, a member of "authenticated", so the
-- original intent is preserved.
--
-- SECURITY MODEL: the application role (app_user) is a NOLOGIN role granted
-- table privileges but owning nothing — RLS therefore applies to every
-- query it runs, exactly as it did under Supabase's "authenticated" role.
-- The owner role (used by bespoke /api routes) still bypasses RLS.

-- Roles -------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='app_user') THEN CREATE ROLE app_user NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role NOLOGIN; END IF;
END $$;
-- The proxy runs queries AS the Supabase role names directly, so policies
-- keep their exact original TO-clause semantics (TO authenticated applies to
-- logged-in requests only; anonymous requests run as anon).
GRANT authenticated TO neondb_owner;
GRANT anon TO neondb_owner;

GRANT USAGE ON SCHEMA public TO authenticated, anon;
-- Full DML to both — RLS policies do the real gating, exactly as Supabase did.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO authenticated, anon;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO authenticated, anon;

-- Actor role helper (complements current_actor_id/current_actor_email)
CREATE OR REPLACE FUNCTION public.current_actor_role() RETURNS text
LANGUAGE sql STABLE AS $$ SELECT current_setting('app.actor_role', true) $$;

-- Policy helper functions referenced by the policies but absent from Neon
-- (extracted from the Supabase dump; auth-free definitions).
CREATE OR REPLACE FUNCTION public.is_admin_raw(user_uuid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.admin_roles
    WHERE user_id = user_uuid AND role IN ('admin', 'super_admin')
  );
$$;

CREATE OR REPLACE FUNCTION public.is_campaign_creator(campaign_uuid uuid, user_uuid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.campaigns
    WHERE id = campaign_uuid AND creator_id = user_uuid
  );
$$;

CREATE OR REPLACE FUNCTION public.check_org_admin(_org_id uuid, _user_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE organization_id = _org_id AND user_id = _user_id
      AND role IN ('admin', 'owner') AND is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION public.check_org_member(_org_id uuid, _user_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE organization_id = _org_id AND user_id = _user_id AND is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION public.is_org_admin(org_uuid uuid, user_uuid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE organization_id = org_uuid AND user_id = user_uuid
      AND role IN ('admin', 'owner', 'manager') AND is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION public.is_org_member(org_uuid uuid, user_uuid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE organization_id = org_uuid AND user_id = user_uuid AND is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION public.is_organization_admin(org_id uuid, user_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM organization_members
    WHERE organization_id = org_id AND user_id = user_id
      AND role = 'admin'::text AND is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION public.is_organization_member(org_id uuid, user_uuid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE organization_id = org_id AND user_id = user_uuid AND is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION public.is_safeguarding_staff(_user_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.safeguarding_roles
    WHERE user_id = _user_id AND is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION public.is_campaign_participant(campaign_uuid uuid, user_uuid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.campaign_participants
    WHERE campaign_id = campaign_uuid AND user_id = user_uuid
  );
$$;

CREATE OR REPLACE FUNCTION public.is_group_admin(p_user_id uuid, p_group_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM groups
    WHERE id = p_group_id AND admin_id = p_user_id
  );
$$;

CREATE OR REPLACE FUNCTION public.is_group_member(p_user_id uuid, p_group_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM group_members
    WHERE user_id = p_user_id AND group_id = p_group_id
  );
$$;

CREATE OR REPLACE FUNCTION public.is_group_public(p_group_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM groups
    WHERE id = p_group_id AND is_private = false
  );
$$;

