-- Policies ------------------------------------------------------------

CREATE POLICY "Admins can delete demo requests" ON public.demo_requests FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.admin_roles
  WHERE ((admin_roles.user_id = public.current_actor_id()) AND (admin_roles.role = 'admin'::text)))));

CREATE POLICY "Admins can manage all badge awards" ON public.badge_award_log USING (public.is_admin(public.current_actor_id()));

CREATE POLICY "Admins can manage all blog posts" ON public.blog_posts USING (public.is_admin(public.current_actor_id()));

CREATE POLICY "Admins can manage badges" ON public.badges USING (public.is_admin(public.current_actor_id()));

CREATE POLICY "Admins can manage blog categories" ON public.blog_categories TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.admin_roles
  WHERE (admin_roles.user_id = public.current_actor_id())))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.admin_roles
  WHERE (admin_roles.user_id = public.current_actor_id()))));

